	if bytes.Equal(badBytes, good) {
		t.Fatalf("未能替换状态字段")
	}
	if err := os.WriteFile(filepath.Join(dir, stateFileName), badBytes, 0o644); err != nil {
		t.Fatal(err)
	}

	// 查询损坏批次、正常批次与配方都必须失败。
